from pathlib import Path
import sys,time,json,hashlib,numpy as np
from quality import linear_scan,linear_spacing
R=Path(__file__).resolve().parent;O=R/'output';sys.path.insert(0,str(Path(__file__).resolve().parents[2]))
d=np.load(str(Path(__file__).resolve().parent/'inputs/volume_input.npz'));old=np.load(str(Path(__file__).resolve().parent/'inputs/volume_input.npz'))['points'];P=np.load(O/(sys.argv[1] if len(sys.argv)>1 else 'gll_constrained.npz'))['points'];H=d['hexes'];L=d['layer_nodes'];Q=d['wall_quads'];start=time.time();report={'points_sha256':hashlib.sha256(P.tobytes()).hexdigest(),'hexes':len(H),'nodes':len(P),'surface_exactly_preserved':bool(np.array_equal(P[L[0]],np.load(R/'inputs/approved_surface.npz')['points'])),'outer_layers_30_through_60_fixed':bool(np.array_equal(P[L[30:]],old[L[30:]])),'scans':{}};arrays={}
for n in [3,5,7]:
 q=linear_scan(P,H,n);report['scans'][str(n)]={'minimum_scaled_Jacobian':float(q.min()),'nonpositive':int(sum(q<=0)),'worst_element':int(q.argmin()),'bad_ids':np.flatnonzero(q<=0).tolist()};arrays['SJ_N'+str(n)]=q;print('N',n,report['scans'][str(n)],'seconds',round(time.time()-start),flush=True)
sp=linear_spacing(P,H,7);arrays['axis_adjacent_GLL_spacing_N7_m']=sp;report['axis_adjacent_GLL_spacing_N7']={'minimum_m':float(sp.min()),'worst_element':int(sp.argmin()),'p01_m':float(np.quantile(sp,.01))};report['displacements']={'max_m':float(np.linalg.norm(P-old,axis=1).max()),'moved_nodes':int(sum(np.linalg.norm(P-old,axis=1)>1e-10)),'moved_nodes_per_layer':[int(sum(np.linalg.norm(P[L[k]]-old[L[k]],axis=1)>1e-10)) for k in range(61)]};(O/'volume_quality.json').write_text(json.dumps(report,indent=2));np.savez_compressed(O/'volume_quality_fields.npz',**arrays);print(json.dumps({k:v for k,v in report.items() if k!='displacements'},indent=2),flush=True)
